            ['category' => 'School Sweaters', 'product' => 'Edelvale Sweater', 'prefix' => 'SW', 'colour' => 'EDELVALE', 'size' => '36', 'price' => 1200.0, 'stock' => 0],
            ['category' => 'School Sweaters', 'product' => 'Edelvale Jss Sweater', 'prefix' => 'SW', 'colour' => 'EDELVALE JSS', 'size' => '22', 'price' => 1200.0, 'stock' => 0],
            ['category' => 'School Sweaters', 'product' => 'Edelvale Jss Sweater', 'prefix' => 'SW', 'colour' => 'EDELVALE JSS', 'size' => '24', 'price' => 1200.0, 'stock' => 0],
            ['category' => 'School Sweaters', 'product' => 'Edelvale Jss Sweater', 'prefix' => 'SW', 'colour' => 'EDELVALE JSS', 'size' => '26', 'price' => 1200.0, 'stock' => 0],
            ['category' => 'School Sweaters', 'product' => 'Edelvale Jss Sweater', 'prefix' => 'SW', 'colour' => 'EDELVALE JSS', 'size' => '28', 'price' => 1200.0, 'stock' => 0],
            ['category' => 'School Sweaters', 'product' => 'Edelvale Jss Sweater', 'prefix' => 'SW', 'colour' => 'EDELVALE JSS', 'size' => '30', 'price' => 1200.0, 'stock' => 0],
            ['category' => 'School Sweaters', 'product' => 'Edelvale Jss Sweater', 'prefix' => 'SW', 'colour' => 'EDELVALE JSS', 'size' => '32', 'price' => 1200.0, 'stock' => 0],
            ['category' => 'School Sweaters', 'product' => 'Edelvale Jss Sweater', 'prefix' => 'SW', 'colour' => 'EDELVALE JSS', 'size' => '34', 'price' => 1200.0, 'stock' => 0],
            ['category' => 'School Sweaters', 'product' => 'Edelvale Jss Sweater', 'prefix' => 'SW', 'colour' => 'EDELVALE JSS', 'size' => '36', 'price' => 1200.0, 'stock' => 0],
        ];

        foreach ($items as $data) {
            $category = $categories[$data['category']] ?? $categories['School Sweaters'];

            // Clean product name
            $prodName = preg_replace('/\s+/', ' ', trim($data['product']));

            // Generate clean concise SKU prefix for products
            $cleanProd = preg_replace('/(\bSchool\b|\bUniform\b|\bOfficial\b)/i', '', $prodName);
            $cleanProd = trim(preg_replace('/[^A-Za-z0-9\s]/', ' ', $cleanProd));
            $words = array_values(array_filter(preg_split('/\s+/', $cleanProd)));

            $skuPrefix = '';
            if (count($words) === 1) {
                $skuPrefix = strtoupper(substr($words[0], 0, 5));
            } elseif (count($words) === 2) {
                $skuPrefix = strtoupper(substr($words[0], 0, 3) . '-' . substr($words[1], 0, 2));
            } else {
                $abbr = '';
                foreach ($words as $w) {
                    $abbr .= strtoupper(substr($w, 0, 1));
                }
                $skuPrefix = strlen($abbr) >= 3 ? $abbr : strtoupper(substr($words[0], 0, 3) . '-' . substr($words[1], 0, 2));
            }

            $product = Product::where('name', $prodName)->orWhere('sku_prefix', $skuPrefix)->first();

            if (!$product) {
                $product = Product::create([
                    'category_id' => $category->id,
                    'name'        => $prodName,
                    'sku_prefix'  => $skuPrefix,
                    'description' => 'Official Tshaprint Solutions ' . $prodName,
                ]);
            } else {
                if ($product->category_id !== $category->id) {
                    $product->update(['category_id' => $category->id]);
                }
            }

            $cleanSize   = strtoupper(preg_replace('/[^A-Za-z0-9]/', '', $data['size']));
            $normColour  = strtolower(preg_replace('/[^a-z0-9]/', '', $data['colour']));
            $normProd    = strtolower(preg_replace('/[^a-z0-9]/', '', $prodName));

            $clrSuffix = '';
            if (!empty($normColour) && $normColour !== $normProd && !str_contains($normProd, $normColour)) {
                $cWords = array_values(array_filter(preg_split('/\s+/', preg_replace('/[^A-Za-z0-9\s]/', ' ', $data['colour']))));
                $cAbbr = '';
                foreach ($cWords as $cw) {
                    $cAbbr .= strtoupper(substr($cw, 0, 1));
                }
                $clrSuffix = '-' . substr($cAbbr, 0, 3);
            }

            $sku = strtoupper($product->sku_prefix . '-' . $cleanSize . $clrSuffix);
            $barcode = 'BC-' . $sku;

            $variant = ProductVariant::where('sku', $sku)->first();

            if (!$variant) {
                $variant = new ProductVariant();
                $variant->product_id     = $product->id;
                $variant->sku            = $sku;
                $variant->barcode        = $barcode;
                $variant->size           = $data['size'];
                $variant->colour         = $data['colour'];
                $variant->selling_price  = $data['price'];
                $variant->stock_quantity = $data['stock'];
                $variant->save();
            }
        }
    }
